Rules.InvariantScript:
Set(currentUserID, Blank());

Navigate(LoginScreen);

Notify(
    "You have been logged out.",
    NotificationType.Information
);

With(
    {
        userEmergencyIds:
            Filter(
                AssignedUsers,
                UserId = currentUserID &&
                AUStatus.Value in ["Accepted", "Pending"]
            ).EmergencyId
    },

    Filter(
        Emergencies,

        ID in userEmergencyIds &&

        With(
            { currentEID: ID },

            CountRows(
                Filter(
                    EmergencySkills,
                    Value(EmergencyId) = Value(currentEID) &&
                    !IsBlank(
                        LookUp(
                            UserQualifications,
                            UserId = currentUserID &&
                            Value(QualificationId) = Value(EmergencySkills[@QualificationId])
                        )
                    )
                )
            ) > 0
        )
    )
)
